<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { Plus, Search, RefreshRight } from '@element-plus/icons-vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { apiRequest } from '../api/request';
import HistoryTaskEditor from '../components/HistoryTaskEditor.vue';
interface Task {id:string;name:string;deviceNames:string[];deviceCount:number;pointCount:number;startAt:string;endAt:string;createdByName:string;createdAt:string;canView:boolean}
const tasks=ref<Task[]>([]),total=ref(0),page=ref(1),keyword=ref(''),loading=ref(false),creating=ref(false),exporting=ref(''),viewing=ref(false),viewTaskId=ref('');
const date=(v:string)=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'});
let generation=0;
async function load(nextPage=page.value){const current=++generation;loading.value=true;try{const data=await apiRequest<{items:Task[];total:number;page:number}>({url:'/api/history-data-tasks',method:'GET',params:{page:nextPage,pageSize:20,keyword:keyword.value}});if(current===generation){tasks.value=data.items;total.value=data.total;page.value=data.page;}}finally{if(current===generation)loading.value=false;}}
function view(task:Task){viewTaskId.value=task.id;viewing.value=true;}
async function saved(){creating.value=false;await load(1);}
async function remove(task:Task){try{await ElMessageBox.confirm(`删除“${task.name}”任务？只删除查询配置，不会删除设备历史数据。`,'删除历史数据任务',{type:'warning',confirmButtonText:'删除任务',cancelButtonText:'取消'});await apiRequest({url:`/api/history-data-tasks/${task.id}`,method:'DELETE'});ElMessage.success('任务已删除');await load();}catch(error){if(error!=='cancel'&&error!=='close')throw error;}}
async function exportTask(task:Task){exporting.value=task.id;try{const data=await apiRequest<{csv:string;exported:number;total:number;limited:boolean}>({url:`/api/history-data-tasks/${task.id}/export`,method:'POST',timeout:60000});const url=URL.createObjectURL(new Blob([data.csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`历史数据-${task.name.replace(/[\\/:*?"<>|]/g,'_')}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(data.limited)ElMessage.warning(`共${data.total}条，本次仅导出最新${data.exported}条，请修改任务时间范围分批导出`);else ElMessage.success(`已导出${data.exported}条历史记录`);}finally{exporting.value='';}}
onMounted(()=>{void load();});
</script>
<template>
<div><div class="page-actions"><div><h1 class="page-title">数据中心</h1><p class="page-description">管理历史数据任务，按保存的设备、点位和时间条件查看或导出</p></div><el-button type="primary" :icon="Plus" @click="creating=true">新增历史数据任务</el-button></div>
<section class="table-panel"><div class="task-toolbar"><el-input v-model="keyword" placeholder="搜索任务名称" clearable :prefix-icon="Search" @keyup.enter="load(1)"/><el-button @click="load(1)">查询</el-button><el-button :icon="RefreshRight" @click="load()">刷新</el-button><span>共 {{total}} 个任务</span></div>
<el-table :data="tasks" v-loading="loading" empty-text="暂无历史数据任务，点击右上角新增" stripe><el-table-column label="任务名称" min-width="200"><template #default="{row}"><el-button link type="primary" :disabled="!row.canView" @click="view(row)">{{row.name}}</el-button></template></el-table-column><el-table-column label="设备 / 点位" min-width="200" show-overflow-tooltip><template #default="{row}">{{row.deviceNames.join('、')}} · {{row.pointCount}}个点位</template></el-table-column><el-table-column label="历史时间范围" min-width="320"><template #default="{row}">{{date(row.startAt)}} 至 {{date(row.endAt)}}</template></el-table-column><el-table-column prop="createdByName" label="创建人" width="120"/><el-table-column label="创建时间" min-width="185"><template #default="{row}">{{date(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="!row.canView" @click="view(row)">查看</el-button><el-button link type="primary" :loading="exporting===row.id" :disabled="!row.canView||!!exporting" @click="exportTask(row)">导出</el-button><el-button link type="danger" @click="remove(row)">删除</el-button><span v-if="!row.canView" class="task-hint">设备权限已变更</span></template></el-table-column></el-table>
<div class="task-footer"><span class="task-hint">任务保存查询条件；历史数据受套餐保存期限限制，不作为永久归档。普通成员管理自己的任务，租户管理员管理本租户任务。</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></section>
<el-dialog v-model="creating" title="新增历史数据任务" width="min(860px, 94vw)" destroy-on-close :close-on-click-modal="false"><HistoryTaskEditor v-if="creating" @saved="saved"/></el-dialog>
<el-dialog v-model="viewing" title="历史数据任务详情" width="min(1200px, 96vw)" top="5vh" class="task-detail-dialog" destroy-on-close :close-on-click-modal="false" @closed="viewTaskId=''" @close="load()"><HistoryTaskEditor v-if="viewing" :key="viewTaskId" :task-id="viewTaskId" @saved="load()"/><template #footer><el-button @click="viewing=false">关闭</el-button></template></el-dialog></div>
</template>
<style>.task-detail-dialog .el-dialog__body{max-height:75vh;overflow:auto}.task-detail-dialog .page-actions{gap:12px;flex-wrap:wrap}.task-detail-dialog .page-actions>div:last-child{display:flex;gap:8px;flex-wrap:wrap}.task-detail-dialog .page-actions .el-button+.el-button{margin-left:0}</style>
<style scoped>.task-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:20px}.task-toolbar .el-input{max-width:340px}.task-toolbar>span{margin-left:auto;color:#7f8da2;font-size:13px}.task-footer{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;margin-top:18px}.task-hint{font-size:12px;color:#8592a5;line-height:1.6}@media(max-width:700px){.page-actions{align-items:flex-start;flex-direction:column;gap:14px}.task-toolbar .el-input{max-width:none;width:100%}.task-footer :deep(.el-pagination){max-width:100%;overflow:auto}}</style>
